import { BrowserRouter, Route, Routes } from 'react-router-dom';
import Home from '../pages/Home.jsx';
importLoca

function AppRouter() {
    return (
        <BrowserRouter>
            <Routes>
                <Route path="/" element={<Home />} />
                <Route path="/teste" element={<Home />} />
            </Routes>
        </BrowserRouter>
    );
}

export default AppRouter;
